public class Main {
    static int 红了几项 = 0;

    static void 查相等(String 名字, int 叼回来, int 该是) {
        if (叼回来 == 该是) {
            System.out.println("绿 " + 名字);
        } else {
            红了几项++;
            System.out.println("红 " + 名字 + "：叼回来 " + 叼回来 + "，该是 " + 该是);
        }
    }

    public static void main(String[] args) {
        查相等("平分六条", (6 + 2 - 1) / 2, 3);
        查相等("除不尽", (7 + 2 - 1) / 2, 3);
        查相等("空碗", (0 + 3 - 1) / 3, 0);
        System.out.println("红了 " + 红了几项 + " 项");
    }
}

public class Main {
    static boolean 查相等(double 叼回来, double 该是) {
        return 叼回来 == 该是;
    }

    static boolean 查接近(double 叼回来, double 该是) {
        return Math.abs(叼回来 - 该是) < 1e-9;
    }

    public static void main(String[] args) {
        double 总数 = 0.1 + 0.2;
        System.out.println(查相等(总数, 0.3));
        System.out.println(查接近(总数, 0.3));
        System.out.println(查相等(1.0 / 4 + 1.0 / 4, 0.5));
    }
}
